/**
 * V2 Data Model Type Definitions
 * 
 * This file documents the V2 data structure to prevent confusion.
 * All V2 components MUST follow these structures.
 */

/**
 * @typedef {Object} V2Subject
 * @property {string} id - Unique subject ID (generated by uid())
 * @property {string} housingUnitId - ID of housing unit containing this subject
 * @property {string} experimentId - ID of experiment this subject belongs to
 * @property {string} subjectId - Human-readable identifier (e.g., "Subject-1", "Mouse-A1")
 * @property {number} slot - Position in housing unit (1-based)
 * @property {'alive'|'deceased'|'removed'|'transferred'} status - Current status (lowercase)
 * @property {string} statusDate - ISO timestamp of last status change
 * @property {Object.<string, any>} customFieldValues - Template-defined custom fields
 * @property {string} groupId - Optional group/cohort identifier
 * @property {string} createdAt - ISO timestamp of creation
 * @property {string} updatedAt - ISO timestamp of last update
 * @property {string} notes - Optional notes
 */

/**
 * @typedef {Object} V2HousingUnit
 * @property {string} id - Unique housing unit ID
 * @property {string} experimentId - ID of experiment this unit belongs to
 * @property {string} name - Display name (e.g., "Cage 1", "Tank A")
 * @property {number} capacity - Maximum number of subjects (default: 10)
 * @property {string} location - Physical location description
 * @property {Object.<string, any>} customFieldValues - Template-defined custom fields
 * @property {string} createdAt - ISO timestamp of creation
 * @property {string} updatedAt - ISO timestamp of last update
 * @property {string} notes - Optional notes
 */

/**
 * @typedef {Object} V2Event
 * @property {string} id - Unique event ID
 * @property {string} subjectId - ID of subject this event belongs to
 * @property {string} experimentId - ID of experiment
 * @property {string} eventTypeId - Type identifier from template
 * @property {string} datetime - ISO timestamp of event occurrence
 * @property {Object.<string, any>} fieldValues - Event-specific data (category, type, etc.)
 * @property {string} notes - Optional notes
 * @property {string} createdAt - ISO timestamp of creation
 * @property {string} updatedAt - ISO timestamp of last update
 */

/**
 * @typedef {Object} V2Experiment
 * @property {string} id - Unique experiment ID
 * @property {string} templateId - ID of template defining this experiment
 * @property {string} name - Experiment name
 * @property {string} description - Experiment description
 * @property {string} startDate - ISO timestamp of start
 * @property {string} [endDate] - ISO timestamp of end (optional)
 * @property {'active'|'completed'|'archived'} status - Current status
 * @property {Object.<string, any>} customFieldValues - Template-defined custom fields
 * @property {string} createdAt - ISO timestamp of creation
 * @property {string} updatedAt - ISO timestamp of last update
 * @property {string[]} tags - Optional tags
 */

/**
 * @typedef {Object} V2Template
 * @property {string} id - Unique template ID
 * @property {string} name - Template name
 * @property {string} version - Template version
 * @property {Object} species - Species configuration
 * @property {string} species.name - Species name (e.g., "Mouse", "Rat")
 * @property {string} species.scientificName - Scientific name
 * @property {Array} species.defaultFields - Default custom fields for subjects
 * @property {Array} eventTypes - Available event types
 * @property {Object} validation - Validation rules
 */

/**
 * IMPORTANT NOTES FOR DEVELOPERS:
 * 
 * 1. Subject Identifier: Use `subject.subjectId` NOT `subject.subject.identifier`
 * 2. Status Values: Always lowercase ('alive', 'deceased', 'removed', 'transferred')
 * 3. Custom Fields: Stored in `customFieldValues` object, NOT as root properties
 * 4. IDs: All IDs are strings generated by uid() function
 * 5. Timestamps: All dates are ISO 8601 strings
 * 
 * COMMON MISTAKES TO AVOID:
 * - ❌ subject.subject.identifier → ✅ subject.subjectId
 * - ❌ subject.status = "ALIVE" → ✅ subject.status = "alive"
 * - ❌ subject.genotype → ✅ subject.customFieldValues.genotype
 * - ❌ cage.id → ✅ housingUnit.id
 * - ❌ mouse → ✅ subject
 */

export const V2_DATA_MODEL_VERSION = "2.0.0";

// Export empty object to make this a module
export default {};

